/* Original review UI. No third-party runtime libraries or assets. */
(()=>{
  'use strict';
  const L=window.ReviewLogic,E=L.escape,SEED=window.ERIGONE_SNAPSHOT,KEY='erigone-release-desk-v1';
  const $=s=>document.querySelector(s);
  let data=structuredClone(SEED),history=[],storageOK=true,pendingImport=null,current='overview',selectedRound=25,selectedCommit=SEED.commits[0].sha;
  let filters={query:'',category:'',status:'',priority:'',critical:false,noIssue:false,sort:'priority'},commitQuery='',commitSystem='';
  try{const old=JSON.parse(localStorage.getItem(KEY)||'null');if(old){L.validate(old.data);data=old.data;history=Array.isArray(old.history)?old.history:[];}}catch(e){storageOK=false;setTimeout(()=>toast('Kayıt okunamadı; kaynak anlık görüntüsü açıldı. JSON yedeğini koru.'),200);}
  const navs=[['overview','◫','Genel bakış'],['checks','☷','Kontrol listesi'],['flow','⌁','50 round & hikâye'],['language','文','Dil kilometre taşları'],['assets','✳','Görsel & bağlantılar'],['licenses','◇','Lisans & credit'],['commits','⇄','Commit karşılaştırma']];
  const summaries={
    'e16acd9f':{title:'Diyalog ve öğretici altyapısı',before:'Bu committe eklenen DialogueDirector, DialogueBox, DialogueProgress ve katalog önceki revision’da yok.',after:'Faz 1–2 tetikleri, kalıcı ilerleme ve diyalog test araçları eklendi. Eski akış raporları güncel adayın testi değildir.',risk:'Menüde input perdesi ve geç oyun öğretimleri yeniden görülmeli.'},
    'be6f1c6d':{title:'Açılış animatiği ve üretim dosyaları',before:'Önceki commit diyalog altyapısını içeriyordu; bu farkta Assets/Scripts değişikliği yok.',after:'Animatik, görsel brief, ses ve üretim araçları ağırlıklı içerik eklendi. Commit başlığı tek başına runtime bağlantısı kanıtı değil.',risk:'Üretilmiş dosya ile oyunda çağrılan varlığı karıştırma.'},
    '75eb6355':{title:'Açılış videosu ve key ikonları',before:'Yeni IntroVideoPlayer ve KeyPrompts çalışma zamanı sınıfları önceki revision’da yok.',after:'Video oynatıcı, ilk Oyna çağrısı, ikon atlas/layout ve ilgili UI çağrıları eklendi.',risk:'İlk açılış, atlama, eksik video ve dil değişimi senaryoları.'},
    '571f29cb':{title:'Unity meta dosyaları',before:'Bir önceki committe eklenen varlık ve betiklerin meta kayıtları eksikti.',after:'Lisans/credit dâhil Unity .meta dosyaları eklendi. Bu değişiklik yeni bir credit ekranı uygulandığını göstermiyor.',risk:'Varlık GUID bağları ve gerçek dağıtım bildirimlerini ayrıca doğrula.'},
    '91422fdd':{title:'Ortak çeviri altyapısı ve Eri taslakları',before:'Diyalog metni DialogueText üzerinden taşınıyordu.',after:'GameText/LocalizedText altyapısına geçiş ve Eri hâlleri için görsel/taslak dosyaları eklendi.',risk:'Görsel dosyaların varlığı, her ifadenin runtime tetiklendiği anlamına gelmez.'},
    '7ae3821d':{title:'Hikâye, dil taşıması ve A1–A2 görselleri',before:'14 taşlık hikâye, kalıcı seçim ve kapsamlı EN/TR taşıması önceki revision ile farklı.',after:'14 taş, kalıcı seçimler, üç Eri atlasının runtime bağı, geniş çeviri taşıması ve A1/A2 shader-perde düzenlemeleri mevcut.',risk:'Zaferi erken atlama, canlı dil değişimi ve A1/A2 görsel regresyonu.'}
  };
  function persist(){try{localStorage.setItem(KEY,JSON.stringify({data,history}));storageOK=true;}catch(e){storageOK=false;toast('Tarayıcı kaydı yazılamadı. Değişiklikleri JSON yedeğiyle dışa aktar.');}updateStorage();}
  function updateStorage(){$('#save-state').textContent=storageOK?'● Tarayıcıda saklanır':'! JSON yedeği gerekli';}
  function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200);}
  function stamp(){return new Date().toISOString();}
  function time(s){return s?new Date(s).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul',dateStyle:'short',timeStyle:'short'}):'Tarih bilinmiyor';}
  function pill(s){return `<span class="pill ${s==='Açık'?'open':s==='Doğrulama bekliyor'?'wait':['Kanıt var','Doğrulandı'].includes(s)?'proof':'unknown'}">${s==='Doğrulandı'?'✓':'•'} ${E(s)}</span>`;}
  function priority(p){return `<span class="priority ${E(p)}">${E(p)}</span>`;}
  function heading(title,desc,action=''){return `<div class="page-heading"><div><span class="eyebrow">YAYIN ÖNCESİ İNCELEME / ERIGONE</span><h1>${title}</h1><p>${desc}</p></div>${action||'<div class="review-badge"><span class="badge-icon">◷</span><div><strong>İnceleme sürüyor</strong><small>07 KASIM 2026 · KAYNAK İNCELEMESİ</small></div></div>'}</div>`;}
  function renderNav(){ $('#navigation').innerHTML=navs.map(([id,icon,title])=>`<a href="#${id}" ${current===id?'class="active" aria-current="page"':''}><span class="nav-symbol" aria-hidden="true">${icon}</span>${title}${id==='checks'?`<span class="nav-count">${data.checks.length}</span>`:''}</a>`).join('');$('#breadcrumb').textContent=navs.find(n=>n[0]===current)?.[2]||'Genel bakış';$('#snapshot-label').textContent=`KAYNAK: ${data.head.slice(0,8)} + yerel değişiklikler · ${data.snapshotDate} · Canlı senkronizasyon yok`;updateStorage();}
  function table(rows,compact=false){if(!rows.length)return `<div class="empty"><span class="eyebrow">BU GÖRÜNÜMDE KAYIT YOK</span><h3>Eşleşen kontrol bulunamadı.</h3><p>Filtreleri genişlet veya yeni bir inceleme maddesi ekle.</p><button class="quiet" data-action="clear">Filtreleri temizle</button></div>`;return `<div class="table-wrap"><table><thead><tr><th>Öncelik</th><th>Kontrol / kaynak</th><th>Durum</th>${compact?'':'<th>Kanıt</th>'}<th></th></tr></thead><tbody>${rows.map(c=>`<tr><td>${priority(c.priority)}</td><td><button class="record-title" data-detail="${E(c.id)}">${E(c.title)}</button><span class="record-sub">${E(c.id)} <span aria-hidden="true">·</span> ${E(c.category)}</span><span class="path-preview" title="${E(c.sources[0]?.path||'Dosya yolu yok')}">${E(c.sources[0]?.path||'⚠ Dosya yolu yok')}${c.sources[0]?.line?':'+c.sources[0].line:''}</span></td><td>${pill(c.status)}</td>${compact?'':`<td><span class="record-sub">${E(c.evidence)}</span><span class="record-sub">${c.issue?'Bağlantı eklendi':'Issue bağlantısı yok'}</span></td>`}<td><button class="text-link" aria-label="${E(c.title)} ayrıntıları" data-detail="${E(c.id)}">↗</button></td></tr>`).join('')}</tbody></table></div>`;}
  function rounds(big=false){return `<div class="panel flow-preview ${big?'flow-big':''}"><div class="panel-head"><h2>50 round. Tek yolculuk.</h2><div class="flow-legend"><span><i class="legend-square"></i>Sınama</span><span><i class="legend-square purple"></i>Hikâye</span></div></div><div class="round-grid">${Array.from({length:50},(_,i)=>i+1).map(r=>`<button class="round ${data.bossRounds.includes(r)?'boss':''} ${data.storyRounds.includes(r)?'story':''} ${selectedRound===r?'selected':''}" data-round="${r}" aria-label="Round ${r}${data.bossRounds.includes(r)?', Sınama':''}${data.storyRounds.includes(r)?', hikâye':''}">${String(r).padStart(2,'0')}</button>`).join('')}</div><div class="round-meta">${big?'Bir round seçerek tetikleri ve bağlı kontrolleri incele.':'15 Sınama · 10 round taşı + ilk Sınama, ilk ödül, zafer ve zafer sonrası = 14 hikâye taşı.'}</div></div>`;}
  function overview(){const critical=L.filter(data.checks,{critical:true}),open=data.checks.filter(c=>c.status==='Açık'),verified=data.checks.filter(c=>c.status==='Doğrulandı');return heading('Yayın öncesi kontrol odası.','Her bulgu bir kaynağa, her düzeltme bir doğrulama adımına bağlı.')+`<div class="stats"><button class="stat" data-action="critical"><span class="stat-label">Kritik takip</span><span class="stat-glyph">↗</span><span class="stat-number">${String(critical.length).padStart(2,'0')}</span><span class="stat-meta">Açık P0 / P1 · önce bunları incele</span></button><button class="stat" data-action="open"><span class="stat-label">Açık bulgu</span><span class="stat-glyph">⚑</span><span class="stat-number">${String(open.length).padStart(2,'0')}</span><span class="stat-meta">Hata / eksik veya koddan çıkarılan risk</span></button><button class="stat" data-action="checks"><span class="stat-label">İnceleme kapsamı</span><span class="stat-glyph">☷</span><span class="stat-number">${data.checks.length}<small> kontrol</small></span><span class="stat-meta">8 alan · issue olmasa da görünür</span></button><button class="stat" data-action="verified"><span class="stat-label">Kapatılmış kontroller</span><span class="stat-glyph">✓</span><span class="stat-number">${String(verified.length).padStart(2,'0')}<small> / ${data.checks.length}</small></span><span class="stat-meta">Kod kanıtı tek başına tamamlandı sayılmaz</span></button></div><div class="banner"><span aria-hidden="true">◈</span><span><b>Güncel build henüz doğrulanmadı.</b> Bu incelemede Unity çalıştırılmadı; geçmiş raporlar ayrıca etiketlendi.</span><a href="#commits">Değişiklikleri gör ↗</a></div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>Önce ele alınacaklar <span class="readiness">P0 / P1</span></h2><small>Öncelik → açık bulgu → kayıt sırası</small></div><button class="text-link" data-action="critical">Tümünü gör ↗</button></div>${table(critical.slice(0,6),true)}<div class="table-foot">${critical.length} kritik takip kaydı. “Kritik takip” kesin hata değil; doğrulama bekleyen yayın kapılarını da içerir.</div></section><aside class="side-stack"><section class="note-card"><span class="eyebrow">BU İNCELEMENİN ODAĞI</span><span class="star" aria-hidden="true">✳</span><h3>Dosya var.<br>Peki oyunda çalışıyor mu?</h3><div class="check-line"><span class="check-num">01</span><span>Varlık → yükleyen kod → tetik</span></div><div class="check-line"><span class="check-num">02</span><span>Dil ve kayıt durumuyla birlikte test</span></div><div class="check-line"><span class="check-num">03</span><span>Son Windows paketinde kanıt</span></div><p>Bağlantı zincirini her kontrolün ayrıntısında takip et.</p><a class="text-link" href="#assets">Görsel & bağlantılar ↗</a></section><section class="panel small-card"><h3>Kaynağın güven sınırı</h3><div class="coverage-row"><span>Kod kanıtı</span><div class="mini-bar"><i style="width:${data.checks.filter(c=>c.evidence==='Kod kanıtı').length/data.checks.length*100}%"></i></div><b>${data.checks.filter(c=>c.evidence==='Kod kanıtı').length}</b></div><div class="coverage-row"><span>Geçmiş rapor</span><div class="mini-bar"><i style="width:${data.checks.filter(c=>c.evidence==='Geçmiş rapor').length/data.checks.length*100}%"></i></div><b>${data.checks.filter(c=>c.evidence==='Geçmiş rapor').length}</b></div><div class="coverage-row"><span>Belirsiz</span><div class="mini-bar"><i style="width:${data.checks.filter(c=>c.evidence==='Belirsiz').length/data.checks.length*100}%"></i></div><b>${data.checks.filter(c=>c.evidence==='Belirsiz').length}</b></div><p class="muted">Canlı issue listesi sorgulanmadı.<br>Kaynak tarihi: ${E(data.snapshotDate)}</p></section></aside></div>${rounds()}<div class="info-box"><b>Tekrar kullanılabilir inceleme alanı.</b> Kontrolleri düzenle, yeni madde ekle ve JSON yedeği al. Kayıtlar bu tarayıcıya özeldir; Git ve Unity ile otomatik eşitlenmez. Sites yayını henüz oluşmadı: bu sürüm yerel çalışır.</div>`;}
  function options(list,value,blank){return (blank?`<option value="">${blank}</option>`:'')+list.map(s=>`<option ${s===value?'selected':''} value="${E(s)}">${E(s)}</option>`).join('');}
  function checks(){return heading('Kontrol listesi.','Açık issue gerektirmez. Bulgu, düzeltme ve doğrulama adımını bir kayıtta tut.',`<button class="button yellow" data-action="add">＋ Yeni kontrol</button>`)+`<div class="toolbar"><label class="search"><span aria-hidden="true">⌕</span><input id="search" placeholder="Bulgu, dosya yolu veya anahtar ara…" aria-label="Kontrolleri ara" value="${E(filters.query)}"></label><select id="filter-category" aria-label="Kategori">${options(L.categories,filters.category,'Tüm alanlar')}</select><select id="filter-status" aria-label="Durum">${options(L.statuses,filters.status,'Tüm durumlar')}</select><select id="filter-priority" aria-label="Öncelik">${options(L.priorities,filters.priority,'Tüm öncelikler')}</select><label class="filter-toggle"><input id="filter-critical" type="checkbox" ${filters.critical?'checked':''}>Kritik açıklar</label><label class="filter-toggle"><input id="filter-noIssue" type="checkbox" ${filters.noIssue?'checked':''}>Issue bağlantısı yok</label></div><div class="filter-summary"><span id="filter-count"></span><div><select id="filter-sort" aria-label="Sıralama"><option value="priority" ${filters.sort==='priority'?'selected':''}>Önem sırası</option><option value="updated" ${filters.sort==='updated'?'selected':''}>Son güncellenen</option></select> <button class="text-link" data-action="clear">Filtreleri temizle</button></div></div><section class="panel" id="check-results"></section><div class="toolbar"><p class="issue-note">${E(data.issueState)}</p><button class="quiet csv-export" data-action="csv">Görünümü CSV indir ↧</button></div>`;}
  function drawResults(){const out=L.filter(data.checks,filters);$('#check-results').innerHTML=table(out);$('#filter-count').textContent=`${out.length} / ${data.checks.length} kontrol · P0 engelleyici / P1 yayın öncesi / P2 iyileştirme / P3 düşük`}
  function flow(){const r=selectedRound,related=data.checks.filter(c=>c.rounds.includes(r));return heading('50 roundluk yolculuk.','Aktif profil, Sınama takvimi ve hikâye taşları. İşaretler ilerleme durumu değil, kaynakta tanımlı tetiklerdir.')+`<div class="two-col flow-layout"><div>${rounds(true)}</div><div><section class="panel check-detail-round"><span class="eyebrow">SEÇİLİ DURAK</span><h3>ROUND ${String(r).padStart(2,'0')}</h3><div class="detail-tags">${data.bossRounds.includes(r)?'<span class="pill wait">Sınama round’u</span>':'<span class="pill">Normal round</span>'}${data.storyRounds.includes(r)?'<span class="pill unknown">Hikâye hazırlıkta</span>':''}</div><p class="muted">${r===25?'R25 konuşması açılırken Eri üzgün aşamaya geçer.':r===50?'Final round; zafer ve ardından story.after ayrı taşlardır.':r===3?'İlk Sınama tamamlanınca story.trial1; ödül alınınca story.reward1.':data.storyRounds.includes(r)?`story.r${r} hazırlık ekranında sırasıyla gösterilir.`:'Bu round için ayrı bir round hikâye taşı tanımlı değil.'}</p><span class="filepath">Assets/Scripts/Dialogue/DialogueProgress.cs:22–32</span></section><h2 class="section-title">Bu durağa bağlı kontroller</h2><div class="panel">${related.length?table(related,true):'<div class="small-card muted">Bu rounda özel kontrol yok. Genel 50 round kontrollerini incele.</div>'}</div></div></div><div class="flow-cards"><section class="flow-card"><span class="eyebrow">BAŞLANGIÇ</span><strong>Menü → seçim → öğretim</strong><p>İlk açılış videosu, tıklama perdesi, T1–T11 tetikleri ve bir kez gösterim.</p><button class="text-link" data-category="Öğretici">Öğretici kontrolleri ↗</button></section><section class="flow-card"><span class="eyebrow">KALICI İLERLEME</span><strong>14 taş, sıralı hikâye</strong><p>İlk Sınama ve ödül + 10 round taşı + zafer ve sonrası. Erken kayıpta ilerleme sonraki run’a taşınır.</p><button class="text-link" data-category="Diyalog">Diyalog kontrolleri ↗</button></section><section class="flow-card"><span class="eyebrow">YAYIN KAPISI</span><strong>R50 → zafer → yeni run</strong><p>Atlama, tekrar açılış, kayıt devamı ve sonlanma birlikte doğrulanmalı.</p><button class="text-link" data-category="50 round">50 round kontrolleri ↗</button></section></div><div class="info-box">Aktif profil: <b>Assets/ScriptableObjects/RunProfiles/Run50_GecOyunV1.asset</b>. Sınama takvimi dosyadan okunmuştur; boss A1/A2 görsel fazlarıyla aynı kavram değildir.</div>`;}
  function language(){let a=data.csvAudit;return heading('Dil kilometre taşları.','EN / TR ana listesi → arayüz bağları → oyuncu paketi. Her aşama ayrı doğrulanır.')+`<section class="panel csv-note"><strong>Yerel CSV alan kontrolü · ${a.rows} satır</strong><p>Boş en: ${a.missing.en.length} · boş tr: ${a.missing.tr.length} · boş not: ${a.missing.note.length} · yinelenen anahtar: ${a.duplicates.length} · İngilizcede Türkçe harf: ${a.turkishInEnglish.length}</p><p>${E(a.scope)} Denetim kaynağı: Assets/Localization/GameText.csv. Sonuç ${E(data.snapshotDate)} anlık görüntüsüne aittir.</p></section><div class="two-col">${[['REV-004','M1','Ana listenin bütünlüğü'],['REV-005','M2','Canlı dil ve UI bağları'],['REV-006','M3','Windows dağıtım paketi'],['REV-007','M4','Yayın dil kapsamı']].map(([id,step,title])=>{let c=data.checks.find(c=>c.id===id);return `<section class="panel milestone"><span class="step">${step}</span><h3>${title}</h3>${c?`${pill(c.status)}<p>${E(c.finding)}</p><button class="text-link" data-detail="${id}">Kanıt ve doğrulama ↗</button>`:'<p>Bu kontrol yedekte bulunamadı. Yeni kayıt eklenebilir.</p>'}</section>`}).join('')}</div><h2 class="section-title">Dil ile kesişen açıklar</h2><div class="panel">${table(L.filter(data.checks).filter(c=>c.category==='Dil'||c.title.toLocaleLowerCase('tr').includes('ipucu')))}</div><div class="info-box">Bu panel yalnız geliştirici incelemesi içindir; oyuncuya yeni yazı eklemez. Bu görevde GameText.csv değiştirilmedi ve Unity LocalizationVerification çalıştırılmadı.</div>`;}
  function assets(){const rows=data.checks.filter(c=>['Boss görselleri','Animasyon & ikon'].includes(c.category));return heading('Görsel varlık → gerçek oyun.','A1–A2 fazları, Eri hâlleri, açılış animasyonu ve tuş ikonları için bağlantı izleri.')+`<div class="banner"><span>◇</span><span>Bu görünüm görsel onay değildir. Kaynak yolu ve çağrı zinciri kanıttır; güncel build görüntüsü olmadan görsel doğrulama tamamlanmış sayılmaz.</span></div><div class="two-col">${rows.map(c=>`<section class="panel asset-chain"><div class="detail-tags">${priority(c.priority)}${pill(c.status)}</div><h3 style="margin-top:15px">${E(c.title)}</h3><p>${E(c.finding)}</p><div class="chain"><span>Varlık</span><b>→</b><span>Yükleyen kod</span><b>→</b><span>Oyun tetiği</span><b>→</b><span>Görsel test ?</span></div><p>${E(c.connection)}</p><span class="path-preview">${E(c.sources[0]?.path||'Dosya yolu yok')}</span><button class="text-link" data-detail="${E(c.id)}">Bağlantıları ve test adımını aç ↗</button></section>`).join('')}</div>`;}
  function licenses(){return heading('Lisans & credit görünürlüğü.','Ücret, ekranda kredi ve paket içi bildirim birbirinden ayrı kontrol edilir.')+`<div class="banner"><span>◇</span><span>Aşağıdaki koşullar mevcut proje envanterinin özetidir; bu oturumda dış lisans metinleri yeniden doğrulanmadı. Yeni üçüncü taraf içerik kullanılmadı.</span></div><div class="panel table-wrap"><table class="license-table"><thead><tr><th>İçerik / kayıt</th><th>Ücret / royalty</th><th>Oyun ekranında kredi</th><th>Paket metni</th></tr></thead><tbody><tr><td><strong>Unity Localization / SmartFormat</strong><span class="record-sub">Envanter: UCL 1.4 / MIT</span></td><td>Kayıtta yok</td><td>Kayıtta zorunlu değil</td><td><span class="pill open">Eksikliği araştırılıyor</span><span class="record-sub">Envanter metinleri gerekli sayıyor</span></td></tr><tr><td><strong>Bungee 2.000</strong><span class="record-sub">Envanter: SIL OFL 1.1</span></td><td>Kayıtta yok</td><td>Kayıtta zorunlu değil</td><td><span class="pill wait">Paket doğrulanmadı</span><span class="record-sub">Telif + OFL gerekli</span></td></tr><tr><td><strong>Kenney Input Prompts 1.5A</strong><span class="record-sub">Envanter: CC0 1.0 · türev atlas</span></td><td>Kayıtta yok</td><td>Kayıtta isteğe bağlı</td><td><span class="pill proof">Kaynakta var</span><span class="record-sub">StreamingAssets / ThirdParty</span></td></tr><tr><td><strong>AI UI / Eri görselleri</strong><span class="record-sub">Kaynağa özel koşullar envanterde</span></td><td>Mevcut üretim abonelik/kredi kaydı var</td><td>Kayıtta zorunlu değil</td><td>Mağaza beyanı doğrulanmadı</td></tr></tbody></table></div><h2 class="section-title">Dağıtım ve görünürlük kontrolleri</h2><section class="panel">${table(L.filter(data.checks,{category:'Lisans & credit'}))}</section><div class="info-box"><b>Kaynak:</b> Docs/ThirdParty-Licenses.md. Geliştirme aracı ile oyunda dağıtılan varlık ayrı tutulur. Credit dosyasının varlığı, oyunda credit ekranı bulunduğunu kanıtlamaz.</div>`;}
  function commits(){let selected=data.commits.find(c=>c.sha===selectedCommit)||data.commits[0],working=selectedCommit==='working',summary=summaries[selected?.short],files=working?data.workingTree:selected?.files||[];const systems=[...new Set(files.map(f=>f.system))];return heading('Son commitlerde ne değişti?','Commit mesajlarıyla sınırlı değil: gerçek dosya farkları, sistemler ve yeniden doğrulanacak davranışlar.')+`<div class="commit-selector">${data.commits.map(c=>`<button class="commit-card ${selectedCommit===c.sha?'selected':''}" data-commit="${E(c.sha)}"><strong>${E(c.short)}</strong><span>${E(summaries[c.short]?.title||c.title)}</span><small>${E(c.date)} · ${c.files.length} dosya</small></button>`).join('')}<button class="commit-card ${working?'selected':''}" data-commit="working"><strong>ÇALIŞMA AĞACI</strong><span>Commitlenmemiş değişiklikler</span><small>${data.workingTree.length} git durum girdisi</small></button></div><section class="panel commit-detail"><span class="eyebrow">${working?'HEAD ÜZERİNE YEREL FARK':'PARENT → SEÇİLİ COMMIT'}</span><h2>${E(working?'UI ve çeviri çalışmaları sürüyor':summary?.title||selected.title)}</h2><p class="muted">${working?'Yeni klasörler Git durum çıktısında tek girdi olabilir; sayı tek tek dosya adedi değildir.':E(selected.title)}</p>${!working?`<a class="text-link" href="${E(data.repository)}/commit/${E(selected.sha)}" target="_blank" rel="noopener">GitHub commit bağlantısı ↗</a> <span class="muted">· erişim ve uzak revision varlığı sorgulanmadı</span>`:''}<div class="compare-cells"><div class="compare-cell"><h4>ÖNCE</h4><p>${E(working?'Son kayıtlı commit 7ae3821d; yerel yeni UI/font dosyalarını kapsamaz.':summary?.before||'Bu commit için davranış özeti hazırlanmadı.')}</p></div><div class="compare-cell"><h4>SONRA</h4><p>${E(working?'HUD, ComicPack, tema, font atlasları, GameText ve UI betikleri değişmiş. Bu panel bunları test edilmiş saymaz.':summary?.after||'Dosya bazlı değişiklik listesi aşağıdadır.')}</p></div></div><div class="banner"><span>↳</span><span><b>Yeniden doğrula:</b> ${E(working?'Yerel değişiklikleri kapsayan Windows build, UI ve çeviri kontrolleri.':summary?.risk||'Etkilenen sistemlerin testleri.')}</span></div><div class="system-tags">${systems.map(s=>`<span class="system-tag">${E(s)} · ${files.filter(f=>f.system===s).length}</span>`).join('')}</div></section><div class="toolbar"><label class="search"><span>⌕</span><input id="commit-search" value="${E(commitQuery)}" placeholder="Değişen dosyalarda ara…" aria-label="Değişen dosyalarda ara"></label><select id="commit-system" aria-label="Değişen sistem">${options(systems,commitSystem,'Tüm sistemler')}</select></div><section class="panel" id="commit-files"></section><p class="muted">Karşılaştırma yerel git geçmişinden çıkarıldı. Binary dosyalarda satır farkı yoktur. Dosya değişimi tek başına çalışır veya tamamlandı demek değildir.</p>`;}
  function drawFiles(){const working=selectedCommit==='working',c=data.commits.find(c=>c.sha===selectedCommit)||data.commits[0],files=(working?data.workingTree:c.files).filter(f=>(!commitSystem||f.system===commitSystem)&&f.path.toLocaleLowerCase('tr').includes(commitQuery.toLocaleLowerCase('tr')));$('#commit-files').innerHTML=`<div class="panel-head"><h2>Değişen dosyalar</h2><small>${files.length} eşleşme${files.length>150?' · ilk 150 gösteriliyor; aramayı daralt':''}</small></div><div class="table-wrap"><table class="file-list"><thead><tr><th>Dosya yolu</th><th>Sistem</th><th>${working?'Git durumu':'Satır farkı'}</th></tr></thead><tbody>${files.slice(0,150).map(f=>`<tr><td class="filepath">${E(f.path)}</td><td>${E(f.system)}</td><td>${working?E(f.status):f.added===null?'Binary':`<span class="diff-add">+${f.added}</span> <span class="diff-delete">−${f.deleted}</span>`}</td></tr>`).join('')||'<tr><td colspan="3">Eşleşen dosya yok.</td></tr>'}</tbody></table></div>`;}
  function render(){current=location.hash.slice(1)||'overview';if(!navs.some(n=>n[0]===current))current='overview';renderNav();const views={overview,checks,flow,language,assets,licenses,commits};$('#main').innerHTML=views[current]();if(current==='checks'){drawResults();$('#search').addEventListener('input',e=>{filters.query=e.target.value;drawResults()});for(const key of ['category','status','priority','critical','noIssue','sort'])$('#filter-'+key).addEventListener('change',e=>{filters[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;drawResults()});}if(current==='commits'){drawFiles();$('#commit-search').addEventListener('input',e=>{commitQuery=e.target.value;drawFiles()});$('#commit-system').addEventListener('change',e=>{commitSystem=e.target.value;drawFiles()});}}
  function navigate(view){if(location.hash==='#'+view)render();else location.hash=view;}
  function sourcesMarkup(c){return c.sources.length?c.sources.map(s=>`<div class="source-box"><div class="filepath">${E(s.path)}${s.line?':'+s.line:''}</div><div class="source-tools"><span>${s.exists===true?'Anlık görüntüde dosya bulundu':s.exists===false?'Dosya bulunamadı':'Dosya yolu doğrulanmadı'} · ${s.workingTree?'yerel değişiklik içeriyor':'kaynak anlık görüntüsü'}</span><button class="text-link" data-copy="${E(s.path)}${s.line?':'+s.line:''}">Yolu kopyala</button></div>${s.exists&&!s.workingTree?`<div class="source-tools"><a class="text-link" href="${E(data.repository)}/blob/${E(data.head)}/${s.path.split('/').map(encodeURIComponent).join('/')}${s.line?'#L'+s.line:''}" target="_blank" rel="noopener">Committeki dosyaya git ↗</a><span>Uzak erişim doğrulanmadı</span></div>`:''}</div>`).join(''):'<p class="status-note">Dosya yolu yok. Bu bulgu için kaynak henüz eklenmedi.</p>';}
  function showDetail(id){const c=data.checks.find(c=>c.id===id);if(!c)return;$('#detail-body').innerHTML=`<div class="detail-top"><div class="dialog-head"><span class="eyebrow">${E(c.id)} / ${E(c.category)}</span><button class="icon-btn" data-close="detail" aria-label="Kapat">×</button></div><h2 id="detail-title">${E(c.title)}</h2><div class="detail-tags">${priority(c.priority)}${pill(c.status)}<span class="pill">${E(c.evidence)}</span></div></div><div class="detail-content"><section class="detail-section"><h3>Bulgu</h3><p>${E(c.finding)}</p></section><section class="detail-section"><h3>Önerilen düzeltme</h3><p>${E(c.fix)}</p></section><section class="detail-section"><h3>Doğrulama adımı</h3><p>${E(c.verify)}</p></section><section class="detail-section"><h3>Doğrulama sonucu</h3><p>${E(c.verificationResult||'Sonuç kaydı yok.')}</p></section><section class="detail-section"><h3>Oyuna bağlantı</h3><p>${E(c.connection||'Bağlantı bilinmiyor.')}</p></section><section class="detail-section"><h3>Dosya yolları / kanıt</h3>${sourcesMarkup(c)}</section><section class="detail-section"><h3>Issue / dış kanıt</h3>${c.issue?`<a class="text-link" href="${E(c.issue)}" target="_blank" rel="noopener">${E(c.issue)} ↗</a>`:'<p class="muted">Bağlantı yok. Canlı issue listesi sorgulanmadı.</p>'}</section><p class="muted">Son kayıt: ${time(c.updatedAt)} · İlgili roundlar: ${c.rounds.length?c.rounds.join(', '):'Belirtilmedi'}</p><div class="dialog-actions"><button class="quiet" data-close="detail">Kapat</button><button class="button" data-edit="${E(c.id)}">Kontrolü düzenle ↗</button></div></div>`;$('#detail').showModal();}
  function edit(id){$('#detail').close();const c=data.checks.find(c=>c.id===id)||{id:'',title:'',category:'Yayın adayı',priority:'P2',status:'Bilinmiyor',evidence:'Belirsiz',sources:[],rounds:[],finding:'',fix:'',verify:'',issue:'',connection:'',verificationResult:''};let f=$('#edit-form');f.reset();for(const key of ['category','priority','status','evidence'])f.elements[key].innerHTML=options(L[key==='category'?'categories':key==='priority'?'priorities':key==='status'?'statuses':'evidence'],c[key]);for(const key of ['id','title','finding','fix','verify','verificationResult','issue','connection'])f.elements[key].value=c[key]||'';f.elements.sources.value=c.sources.map(s=>s.path+(s.line?':'+s.line:'')).join('\n');f.elements.rounds.value=c.rounds.join(', ');$('#edit-title').textContent=id?'Kontrolü düzenle':'Yeni kontrol ekle';$('#edit').showModal();}
  function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));let a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportJSON(){download('erigone-review-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({...data,exportedAt:stamp(),history},null,2),'application/json');toast('JSON yedeği indirildi; tarayıcı dışına taşıyabilirsin.');}
  $('#edit-form').addEventListener('submit',e=>{e.preventDefault();const f=e.target,values=Object.fromEntries(new FormData(f));let old=data.checks.find(c=>c.id===values.id);let rounds=values.rounds.split(',').filter(v=>v.trim()).map(Number);if(rounds.some(r=>!Number.isInteger(r)||r<1||r>50)){toast('Roundlar 1–50 arasında tam sayı olmalı.');return;}if(values.status==='Doğrulandı'&&(!values.verificationResult.trim()||values.verificationResult.includes('çalıştırılmadı'))){toast('Doğrulandı demeden önce gerçek test sonucunu ve kanıtını ekle.');return;}if(values.issue&&!/^https?:\/\//i.test(values.issue)){toast('Bağlantı http veya https ile başlamalı.');return;}const sources=values.sources.split('\n').filter(v=>v.trim()).map(v=>{const m=v.trim().match(/^(.*?):(\d+)$/);const path=m?m[1]:v.trim(),line=m?Number(m[2]):null;const prior=old?.sources.find(s=>s.path===path&&s.line===line);return prior?{...prior}:{path,line,exists:null,workingTree:true}});let c={...old,...values,id:values.id||'USR-'+Date.now().toString(36).toUpperCase(),sources,rounds:[...new Set(rounds)],updatedAt:stamp()};if(!old)data.checks.push(c);else data.checks[data.checks.indexOf(old)]=c;history.unshift({at:c.updatedAt,id:c.id,action:old?'Güncellendi':'Eklendi'});history=history.slice(0,100);persist();$('#edit').close();render();toast('Kontrol saklandı. Oyun dosyaları değişmedi.');});
  $('#export-btn').addEventListener('click',exportJSON);$('#import-btn').addEventListener('click',()=>$('#import-file').click());
  $('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>12*1024*1024)throw Error('Dosya en fazla 12 MB olabilir.');pendingImport=L.validate(JSON.parse(await file.text()));$('#import-summary').innerHTML=`<div class="info-box"><b>${pendingImport.checks.length} kontrol · ${pendingImport.commits.length} commit</b><br>Kaynak tarihi: ${E(pendingImport.snapshotDate)}<br>Mevcut ${data.checks.length} kontrolün yerini alacak.</div>`;$('#import-dialog').showModal();}catch(err){toast('İçe aktarma başarısız: '+err.message);}e.target.value='';});
  $('#confirm-import').addEventListener('click',()=>{if(!pendingImport)return;data=structuredClone(pendingImport);history=Array.isArray(data.history)?data.history:[];history.unshift({at:stamp(),action:'JSON içe aktarıldı',id:'snapshot'});selectedCommit=data.commits[0]?.sha||'working';pendingImport=null;persist();$('#import-dialog').close();render();toast('Yedek uygulandı. Kaynak tarihi panelde güncellendi.');});
  document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.close){$('#'+el.dataset.close).close();return;}if(el.dataset.detail){showDetail(el.dataset.detail);return;}if(el.dataset.edit){edit(el.dataset.edit);return;}if(el.dataset.copy){try{await navigator.clipboard.writeText(el.dataset.copy);toast('Dosya yolu kopyalandı.');}catch{toast('Kopyalama kullanılamıyor; gösterilen dosya yolunu seçip kopyala.');}return;}if(el.dataset.round){selectedRound=Number(el.dataset.round);navigate('flow');return;}if(el.dataset.commit){selectedCommit=el.dataset.commit;commitSystem='';commitQuery='';render();return;}if(el.dataset.category){filters={...filters,category:el.dataset.category,query:'',status:'',critical:false};navigate('checks');return;}switch(el.dataset.action){case 'add':edit();break;case 'critical':filters={query:'',category:'',status:'',priority:'',critical:true,noIssue:false,sort:'priority'};navigate('checks');break;case 'open':filters={...filters,query:'',category:'',status:'Açık',critical:false};navigate('checks');break;case 'verified':filters={...filters,query:'',category:'',status:'Doğrulandı',critical:false};navigate('checks');break;case 'checks':navigate('checks');break;case 'clear':filters={query:'',category:'',status:'',priority:'',critical:false,noIssue:false,sort:'priority'};render();break;case 'csv':{const cols=['id','title','category','status','priority','finding','fix','verify','verificationResult','connection','issue','updatedAt'];const rows=L.filter(data.checks,filters);download('erigone-kontrol-listesi.csv','\ufeff'+[cols.concat('sources').map(L.csvCell).join(','),...rows.map(c=>cols.map(k=>L.csvCell(c[k])).concat(L.csvCell(c.sources.map(s=>s.path+(s.line?':'+s.line:'')).join(' | '))).join(','))].join('\r\n'),'text/csv;charset=utf-8');toast(rows.length+' kontrol CSV olarak indirildi.');break;}}});
  window.addEventListener('hashchange',render);render();if(data.generatedAt!==SEED.generatedAt)setTimeout(()=>toast('Saklanan inceleme açıldı. Yeni kaynak snapshot.json dosyasını içe aktarabilirsin.'),500);
})();
